body.script:
$(document).ready(function() {
    console.log('Default B92');

    //CLICK INPUT SEARCH
    $('#search-404').on('click', function (e) {

        e.preventDefault();

        let searchTerm = $('#search-term').val();

        searchTerm = searchTerm.replaceAll(' ','+');

        console.log('searchTerm', searchTerm);

        // var url = "https://www.b92.net/najnovije-vesti";
        // let url = '/najnovije-vesti'
        let url = "https://www.b92.net/najnovije-vesti";

        if(searchTerm){
            if (searchTerm.length < 3) {
                console.log('manje od 3');
                const errorMessage = 'Parametar po kome pretražujete mora biti duži od 2 karaktera.';
                document.querySelector('.error-message').innerText = errorMessage;
                return;
            }
            if (searchTerm.length > 50) {
                console.log('vise od 50');
                const errorMessage = 'Parametar po kome pretražujete ne sme biti duži od 50 karaktera.';
                document.querySelector('.error-message').innerText = errorMessage;
                return;
            }
        }
        // var url = "https://www.b92.net/najnovije-vesti";
        url+= "?search=" + searchTerm;

        window.location.href = url;
    });
});
